import re
import sqlite3
from functools import lru_cache
import numpy as np

# Regex compilada UNA VEZ (fuera del bucle)
_PATRON_PRECIO = re.compile(r'\$?\s*([\d,]+(?:\.\d{2})?)')

@lru_cache(maxsize=1024)
def parsear_precio(precio_str):
    '''Cache para precios repetidos'''
    match = _PATRON_PRECIO.search(precio_str)
    if match:
        return float(match.group(1).replace(',', ''))
    return None

def pipeline_optimizado(registros):
    # 1. Limpieza de texto con generador (memoria O(1))
    def limpiar_registro(registro):
        texto = re.sub(r'\s+', ' ', registro['texto']).strip()
        return {'texto': texto, 'precio': registro['precio']}

    limpios = (limpiar_registro(r) for r in registros)  # Generador

    # 2. Parseo de precios con cache y regex compilada
    def parsear_registro(registro):
        precio = parsear_precio(registro['precio'])
        return {'texto': registro['texto'], 'precio': precio}

    precios = (parsear_registro(r) for r in limpios)  # Generador

    # 3. Filtrado con generador
    validos = (r for r in precios if r['precio'] and r['precio'] > 10)

    # 4. Carga a SQLite con executemany (batch insert)
    conn = sqlite3.connect('dataset.db')
    datos = [(r['texto'], r['precio']) for r in validos]
    conn.executemany('INSERT INTO items (texto, precio) VALUES (?, ?)', datos)
    conn.commit()
    conn.close()

    return len(datos)

